export function CookieConsentBanner({
  message = "{{message}}",
  acceptText = "{{acceptText}}",
  position = "{{position}}",
  accent = "{{accent}}",
  showManage = {{showManage}},
}) {
  const isBar = position === "bottom-bar" || position === "top-bar";
  const wrapStyle = isBar
    ? { display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16, width: "100%", padding: "14px 20px" }
    : { maxWidth: 320, padding: 18, borderRadius: 14 };
  return (
    <div role="region" aria-label="Cookie consent" style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430",
      background: "#FAF7F2", border: "1px solid #24143022", boxShadow: "0 8px 24px rgba(36,20,48,.14)", ...wrapStyle }}>
      <p style={{ margin: isBar ? 0 : "0 0 14px" }}>{message}</p>
      <div style={{ display: "flex", gap: 8, flexShrink: 0, flexWrap: isBar ? "nowrap" : "wrap" }}>
        {showManage && (
          <button type="button" style={{ background: "transparent", border: "1.5px solid #24143033", color: "#241430",
            padding: "8px 14px", borderRadius: 8, fontWeight: 600, cursor: "pointer" }}>Manage preferences</button>
        )}
        <button type="button" style={{ border: "none", color: "#FAF7F2", padding: "8px 16px", borderRadius: 8,
          fontWeight: 700, cursor: "pointer", background: accent }}>{acceptText}</button>
      </div>
    </div>
  );
}
